"""Review computation (RB-4) for TASK-20261002-4cb903 (J5, J7, PTM-A..PTM-F).

This reviewer's OWN closed-form implementation of the contract's formulas, as
EXP-NISTBIN-451dfa version 3 states them (definitions.A, instrument_value,
reading_R_B, reading_R_M, rho, margin, coherent_shift, IR-3 rho_ub). It imports
neither experiments/EXP-SEMBIN-81dc96/code/joint_balance.py nor CB-2, runs no
solver, instantiates no curve, and re-measures no SEMBIN or SDEG quantity.

Two independent evaluations of A(n, m) = k - log2 P, P = 1 - exp(-2^(mk-n)/m!):
  IMPL-F  binary floating point (math.expm1, math.log2, math.lgamma-free factorial)
  IMPL-D  decimal.Decimal at 60 significant digits (exp, ln), exact rationals for k
Outcome discipline: D* values at 571 are computed only inside the SR-3 check and
are NOT printed (see the report's disclosure); only aggregates are printed.
"""
import json, math, sys, functools
from decimal import Decimal, getcontext
from fractions import Fraction

getcontext().prec = 60
P = json.load(open(sys.argv[1]))          # params.out from params.py
OMEGAS = [3.0, 2.807, 2.376, 2.0]
M_LO, M_HI = 2, 30
LN2 = Decimal(2).ln()

def k_of(n, m, reading):
    return Fraction(n, m) if reading == "MI-1" else Fraction(-(-n // m))

# ---------------------------------------------------------------- A(n, m)
@functools.lru_cache(maxsize=None)
def A_float(n, m, reading):
    k = k_of(n, m, reading)
    log2_x = float(m * k - n) - math.log2(math.factorial(m))
    return float(k) - math.log2(-math.expm1(-(2.0 ** log2_x)))

@functools.lru_cache(maxsize=None)
def A_dec(n, m, reading):
    k = k_of(n, m, reading)
    e = m * k - n                      # an integer under both readings (0 under MI-1)
    assert e.denominator == 1
    x = (Decimal(2) ** int(e)) / Decimal(math.factorial(m))
    p = 1 - (-x).exp()
    kd = Decimal(k.numerator) / Decimal(k.denominator)
    return kd - p.ln() / LN2

@functools.lru_cache(maxsize=None)
def log2_dec(v):
    return Decimal(v).ln() / LN2

@functools.lru_cache(maxsize=None)
def W_exact(n, D):
    return log2_dec(sum(math.comb(n, d) for d in range(D + 1)))

def C_I(n, omega, reading, impl="F"):
    """first minimum over m = 2..min(30, n), ascending, strict less-than."""
    best, arg = None, None
    for m in range(M_LO, min(M_HI, n) + 1):
        if impl == "F":
            v = A_float(n, m, reading) + 4 * omega * math.log2(n)
        else:
            v = A_dec(n, m, reading) + Decimal(4) * Decimal(str(omega)) * log2_dec(n)
        if best is None or v < best:
            best, arg = v, m
    return best, arg

# ---------------------------------------------------------------- rho
rho = {}
curves_at = {}
for c in P["certicom_binary_rows"]:
    rho[c["curve"]] = c["rho_corrected"]
    curves_at.setdefault(c["m"], []).append(c["curve"])
for f in P["fips_rows"]:
    rho[f["curve"]] = f["rho_corrected"]
    curves_at.setdefault(f["m"], []).append(f["curve"])
def rho_ub(n):
    return 0.5 * math.log2(math.pi * (2**n + 1 + 2**(n / 2 + 1)) / 8)
for n in (155, 185):
    rho["Oakley-%d(rho_ub)" % n] = rho_ub(n)
    curves_at.setdefault(n, []).append("Oakley-%d(rho_ub)" % n)
DEGREES = sorted(curves_at)

out = {"implementations": ["IMPL-F float", "IMPL-D Decimal prec 60"], "python": sys.version.split()[0]}

# ---------------------------------------------------------------- C_I table, both readings, all omegas
ci = {}
impl_gap = 0.0
for n in DEGREES:
    for rd in ("MI-1", "ceiled"):
        for w in OMEGAS:
            vf, af = C_I(n, w, rd, "F")
            vd, ad = C_I(n, w, rd, "D")
            impl_gap = max(impl_gap, abs(vf - float(vd)))
            assert af == ad, (n, rd, w, af, ad)
            ci[(n, rd, w)] = (vf, af)
out["C_I_impl_F_vs_D_max_abs_diff_bits"] = impl_gap
out["C_I_omega3"] = {str(n): {"MI-1": [round(ci[(n, "MI-1", 3.0)][0], 4), ci[(n, "MI-1", 3.0)][1]],
                              "ceiled": [round(ci[(n, "ceiled", 3.0)][0], 4), ci[(n, "ceiled", 3.0)][1]],
                              "move_ceiled_minus_MI1": round(ci[(n, "ceiled", 3.0)][0] - ci[(n, "MI-1", 3.0)][0], 4)}
                     for n in DEGREES}

# ---------------------------------------------------------------- fixture F1 (G2) and ceiled F1
def fx(n, target, mstar, rd):
    v, a = ci[(n, rd, 3.0)]
    return {"C_I": round(v, 7), "argmin": a, "abs_diff": abs(v - target), "within_5e-4": abs(v - target) <= 5.0e-4 and a == mstar,
            "slack_bits": round(5.0e-4 - abs(v - target), 9)}
out["F1"] = {"571_MI-1": fx(571, 186.307, 12, "MI-1"), "283_MI-1": fx(283, 147.649, 9, "MI-1"),
             "571_ceiled": fx(571, 186.307, 12, "ceiled"), "283_ceiled": fx(283, 147.649, 9, "ceiled")}

# ---------------------------------------------------------------- time-only corrected margins per curve
def margin(n, c, rd, w):
    return ci[(n, rd, w)][0] - rho[c]
marg = {}
for n in DEGREES:
    for c in curves_at[n]:
        marg[c] = {rd: {str(w): round(margin(n, c, rd, w), 4) for w in OMEGAS} for rd in ("MI-1", "ceiled")}
out["time_only_corrected_margins"] = marg

# ---------------------------------------------------------------- G4 (stage 4): MI-1 gated, ceiled reported
G4_SET = [("K-283", 283), ("B-283", 283), ("K-163", 163), ("B-163", 163), ("K-233", 233), ("B-233", 233),
          ("ECC2-238", 239), ("ECC2K-238", 239)]
g4 = {}
for c, n in G4_SET:
    g4[c] = {"MI-1_omega3": round(margin(n, c, "MI-1", 3.0), 4), "ceiled_omega3": round(margin(n, c, "ceiled", 3.0), 4)}
out["G4"] = {"margins": g4,
             "pass_under_MI-1_omega3": all(v["MI-1_omega3"] > 0 for v in g4.values()),
             "pass_under_ceiled_omega3": all(v["ceiled_omega3"] > 0 for v in g4.values()),
             "min_MI-1": min((v["MI-1_omega3"], c) for c, v in g4.items()),
             "min_ceiled": min((v["ceiled_omega3"], c) for c, v in g4.items())}
# omega at which B-283's ceiled margin reaches zero (linear in omega: margin(w) = margin(3) - 4 (3 - w) log2 n)
m3 = margin(283, "B-283", "ceiled", 3.0)
out["G4"]["B-283_ceiled_zero_omega"] = round(3.0 - m3 / (4 * math.log2(283)), 4)
m3 = margin(283, "B-283", "MI-1", 3.0)
out["G4"]["B-283_MI-1_zero_omega"] = round(3.0 - m3 / (4 * math.log2(283)), 4)

# ---------------------------------------------------------------- G4 degree rule (contract) and PTM-E rule R-E-4cb903
RESULTS_CERTICOM = [97, 109, 131, 163, 191, 239]     # degrees EXP-SEMBIN-992e73 RESULTS.md tabulates for Certicom binary rows
cert_curves = {c["curve"] for c in P["certicom_binary_rows"]}
rule_rows = []
for n in RESULTS_CERTICOM:
    cs = [c for c in curves_at[n] if c in cert_curves]
    mi1 = min(margin(n, c, "MI-1", 3.0) for c in cs)
    cei = min(margin(n, c, "ceiled", 3.0) for c in cs)
    rule_rows.append({"m": n, "curves": cs, "min_MI1_corrected": round(mi1, 4), "min_ceiled_corrected": round(cei, 4),
                      "mu_min_R-E": round(min(mi1, cei), 4)})
ptm_e = min(rule_rows, key=lambda r: (r["mu_min_R-E"], -r["m"]))
contract_rule = min(rule_rows, key=lambda r: (r["min_MI1_corrected"], -r["m"]))
out["G4_degree_rules"] = {"rows": rule_rows, "contract_rule_corrected_MI1_argmin": contract_rule["m"],
                          "PTM-E_rule_R-E-4cb903_argmin": ptm_e["m"]}

# ---------------------------------------------------------------- PTM-A: 283 surface near D = 4 (R-B and R-M), MI-1, omega 3
def CB(n, D, w, rd="MI-1"):
    a = min(A_float(n, m, rd) for m in range(M_LO, min(M_HI, n) + 1))
    return a + D * w * math.log2(n)
def CM(n, D, w, rd="MI-1"):
    a = min(A_float(n, m, rd) for m in range(M_LO, min(M_HI, n) + 1))
    return a + w * (float(W_exact(n, D)) - float(W_exact(n, 4)) + 4 * math.log2(n))
ptm_a = {}
for c in ("K-283", "B-283"):
    ptm_a[c] = {"R-B": {str(D): round(CB(283, D, 3.0) - rho[c], 4) for D in (2, 3, 4, 5)},
                "R-M": {str(D): round(CM(283, D, 3.0) - rho[c], 4) for D in (2, 3, 4, 5)}}
out["PTM-A_283_margins_by_D"] = ptm_a

# ---------------------------------------------------------------- PTM-C: 409 against the naive and corrected columns; delta(c)
c409 = ci[(409, "MI-1", 3.0)][0]
def delta(c, n, log2r, k):
    return 0.5 * (n - log2r) + 0.5 * math.log2(k) + (math.log2(0.886) - 0.5 * math.log2(math.pi / 4))
fr = {f["curve"]: f for f in P["fips_rows"]}
out["PTM-C_409"] = {"C_I_409_MI1": round(c409, 4),
                    "margin_vs_naive_2^(n/2)": round(c409 - 409 / 2.0, 4),
                    "margin_vs_vOW_0.886*2^(n/2)": round(c409 - (409 / 2.0 + math.log2(0.886)), 4),
                    "margin_vs_corrected": {c: round(c409 - rho[c], 4) for c in ("K-409", "B-409")},
                    "delta_c": {c: round(delta(c, 409, fr[c]["log2_r"], fr[c]["k"]), 4) for c in ("K-409", "B-409")},
                    "SN1_check_design_figures": {"COST-SEMBIN-8d123b_time_only_+37.78_vs_minus(-37.781)": round(abs(37.78 - 37.781), 4)}}

# ---------------------------------------------------------------- C-RHOCONV (G1)
ell = 680564733841876926932320129493409985129      # Bailey paper_fulltext.md line 1096
rhoconv = 0.5 * math.log2(math.pi * ell / (4 * 131)) + math.log2(1.069993)
ecc2k130_r = [c for c in P["certicom_binary_rows"] if c["curve"] == "ECC2K-130"][0]
out["C-RHOCONV"] = {"value": round(rhoconv, 6), "printed": 60.9, "abs_diff": round(abs(rhoconv - 60.9), 6),
                    "pass_0.05": abs(rhoconv - 60.9) <= 0.05,
                    "bailey_ell_log2": round(math.log2(ell), 6), "certicom_ECC2K-130_log2_r": ecc2k130_r["log2_r"]}

# ---------------------------------------------------------------- F2, F3 (G3 / C-INT) residuals and C-ARG
def CI_inst(n, w):  # instrument convention: k + S - log2P, same algebra, separate summation order
    best, arg = None, None
    for m in range(M_LO, min(M_HI, n) + 1):
        k = float(k_of(n, m, "MI-1"))
        log2_x = float(m * k_of(n, m, "MI-1") - n) - math.log2(math.factorial(m))
        v = k + 4 * w * math.log2(n) - math.log2(-math.expm1(-(2.0 ** log2_x)))
        if best is None or v < best:
            best, arg = v, m
    return best, arg
f2 = 0.0
for n in (571, 283):
    for w in (2.0, 2.376, 2.807, 3.0):
        f2 = max(f2, abs(CB(n, 4, w) - CI_inst(n, w)[0]), abs(CM(n, 4, w) - CI_inst(n, w)[0]))
f3 = 0.0
for n, m, l in ((571, 12, 48), (283, 9, 32)):
    nvar = m * l
    k = n / m
    for w in (2.0, 2.376, 2.807, 3.0):
        ill = l + w * math.log2(math.comb(nvar, 4))
        M1 = k - l
        M2 = math.log2(math.factorial(m)) + (n - m * k) + (-math.log2(-math.expm1(-1.0 / math.factorial(m))) - math.log2(math.factorial(m)))
        M3 = 4 * math.log2(n) - math.log2(math.comb(nvar, 4))
        f3 = max(f3, abs(ill + M1 + M2 + w * M3 + 0.0 - CI_inst(n, w)[0]))
carg = {}
for n, want in ((571, 12), (283, 9)):
    for rd in ("MI-1", "ceiled"):
        args = set()
        for w in OMEGAS:
            for D in range(2, 65):
                for reading in ("R-B", "R-M"):
                    best, arg = None, None
                    S = D * w * math.log2(n) if reading == "R-B" else w * (float(W_exact(n, D)) - float(W_exact(n, 4)) + 4 * math.log2(n))
                    for m in range(M_LO, min(M_HI, n) + 1):
                        v = A_float(n, m, rd) + S
                        if best is None or v < best:
                            best, arg = v, m
                    args.add(arg)
        carg["%d_%s" % (n, rd)] = {"argmins_over_grid": sorted(args), "C-ARG_pass": args == {want}}
out["G3"] = {"F2_max_residual_bits": f2, "F2_pass_1e-9": f2 <= 1e-9, "F3_max_residual_bits": f3, "F3_pass_1e-9": f3 <= 1e-9,
             "C-ARG": carg}

# ---------------------------------------------------------------- SR-3 / C-IND false-FAIL exposure on the 571 grid
# D* values are computed here and NOT printed. Report: do IMPL-F and IMPL-D agree on every D*, and the
# smallest |mu| over the grid (how close any cell sits to the strict > 0 boundary).
def dstar_table(impl):
    res = {}
    minabs = None
    for c in ("K-571", "B-571"):
        r = Decimal(str(rho[c])) if impl == "D" else rho[c]
        for rd in ("R-B", "R-M"):
            for w in OMEGAS:
                for m in range(M_LO, M_HI + 1):
                    a = A_dec(571, m, "MI-1") if impl == "D" else A_float(571, m, "MI-1")
                    ds = None
                    for D in range(2, 65):
                        if rd == "R-B":
                            S = (Decimal(D) * Decimal(str(w)) * log2_dec(571)) if impl == "D" else D * w * math.log2(571)
                        else:
                            S = (Decimal(str(w)) * (W_exact(571, D) - W_exact(571, 4) + 4 * log2_dec(571))) if impl == "D" else w * (float(W_exact(571, D)) - float(W_exact(571, 4)) + 4 * math.log2(571))
                        mu = a + S - r
                        av = abs(float(mu))
                        minabs = av if minabs is None or av < minabs else minabs
                        if ds is None and mu > 0:
                            ds = D
                    res[(c, rd, w, m)] = ds
    return res, minabs
tf, minf = dstar_table("F")
td, mind = dstar_table("D")
out["SR3_CIND_exposure"] = {"cells": len(tf), "D_star_agree_all_cells": tf == td,
                            "min_abs_mu_bits_float": round(minf, 6), "min_abs_mu_bits_decimal": round(float(mind), 6),
                            "note": "rho taken at 6-decimal precision from params.out in both implementations; D* values not printed"}
# ---------------------------------------------------------------- RT-4 sign table under MI-1 vs the pre-registered table
pre = {79: "++++", 89: "++++", 97: "++++", 109: "++++", 131: "++++", 155: "++++", 163: "++++", 185: "++++",
       191: "++++", 233: "+++-", 239: "+++-", 283: "++--", 359: "----", 409: "----", 571: "----"}
rt4 = {}
for n in DEGREES:
    got = ""
    per_curve = {}
    for i, w in enumerate(OMEGAS):
        signs = ["+" if margin(n, c, "MI-1", w) > 0 else "-" for c in curves_at[n]]
        per_curve[str(w)] = dict(zip(curves_at[n], signs))
        got += signs[0] if len(set(signs)) == 1 else "?"
    ceiled = ""
    for w in OMEGAS:
        signs = ["+" if margin(n, c, "ceiled", w) > 0 else "-" for c in curves_at[n]]
        ceiled += signs[0] if len(set(signs)) == 1 else "?"
    rt4[str(n)] = {"preregistered": pre[n], "MI-1": got, "matches": got == pre[n], "ceiled_would_be": ceiled}
out["RT4_signs_order_3.0_2.807_2.376_2.0"] = rt4
print(json.dumps(out, indent=1, default=str))

