"""Review computation (RB-4): a synthetic encoding of EXP-NISTBIN-451dfa version 3's
baseline_rule BR-1 (with pinned_coherent_row, exact_n_only, multi_match_rule,
unresolved_level_pin), SN-1 and IR-1, written by this reviewer FROM THE CONTRACT
TEXT, applied to the proves-too-much objects PTM-C, PTM-C-SLICE, PTM-D and PTM-F.
Inputs are abstract: signs of coherent margins are taken from H-SEMBIN-97ea23's
supported claim C1 (coherent crossovers above 409 under all four storage readings);
no SEMBIN quantity is re-measured and no record value is imported. Time-only margins
are this reviewer's own closed-form values (model.out). It encodes this reviewer's
reading of the rules, not the executor's code.
"""
import json, math, sys

M = json.load(open(sys.argv[1]))   # model.out
STORAGE = ["dense_row_echelon", "semaev_sparse", "rows_times_cols_dense", "nonzeros_with_index_sparse"]
PIN = {"cofactor": 1, "label_separated": False, "degree_bound": 4, "k_reading": "unceiled_n_over_m_as_in_table3",
       "metric": "own_curve_product_minimum"}

def pinned(row, omega, kappa):
    reasons = []
    for f, v in PIN.items():
        if row.get(f) != v:
            reasons.append("pin field %s=%r != %r" % (f, row.get(f), v))
    if row.get("omega") != omega: reasons.append("omega %r != scored %r" % (row.get("omega"), omega))
    if row.get("kappa") != kappa: reasons.append("kappa %r != %r" % (row.get("kappa"), kappa))
    if row.get("storage") not in STORAGE: reasons.append("storage %r not one of the four" % row.get("storage"))
    return reasons

def import_rows(rows, n, omega, kappa, sn1_ok):
    """Return per-storage imported contract-sign margins, or refusals (UNRESOLVED)."""
    if not sn1_ok:
        return None, ["SN-1 failed or record not located: no SEMBIN margin imported"]
    out, refusals = {}, []
    for st in STORAGE:
        cand = [r for r in rows if r.get("storage") == st and r.get("n") == n]
        ok = [r for r in cand if not pinned(r, omega, kappa)]
        for r in cand:
            p = pinned(r, omega, kappa)
            if p: refusals.append("refused %s: %s" % (r.get("tag"), "; ".join(p)))
        if len(ok) > 1:
            refusals.append("multi_match_rule: %d rows match the pin at (%d, %s); none chosen" % (len(ok), n, st))
            out[st] = None
        elif len(ok) == 1:
            out[st] = -ok[0]["sembin_margin"]          # SN-1 negation into contract sign
        else:
            out[st] = None                              # exact_n_only / nothing pinned
    return out, refusals

def classify_curve(imported, delta, time_only_corrected, naive_offered=None):
    """BR-1 for one curve. naive_offered is never read (THE NAIVE COLUMN NEVER ENTERS BR-1)."""
    if imported and all(v is not None for v in imported.values()):
        shifted = {k: v + delta for k, v in imported.items()}
        if all(v < 0 for v in shifted.values()):
            return "IC", "coherent shifted margin negative under every storage reading", shifted
        if all(v >= 0 for v in shifted.values()):
            return "RHO", "clause (a)", shifted
    if time_only_corrected is not None and time_only_corrected > 0:
        return "RHO", "clause (b) (time-only positive; L-MONO)", None
    return "UNRESOLVED", "no complete coherent import and time-only not positive (time-only never makes IC)", None

def degree_class(curve_classes):
    if any(c == "IC" for c in curve_classes): return "MODEL-CLASS-IC"
    if all(c == "RHO" for c in curve_classes): return "MODEL-CLASS-RHO"
    return "UNRESOLVED"

res = {}
tom = M["time_only_corrected_margins"]
pc = M["PTM-C_409"]
# --------------------------------------------------- PTM-C: 409 read against the naive column
# Coherent sign from H-SEMBIN-97ea23 C1 (supported): rho cheaper at 409 under all four readings.
# In SEMBIN's sign (rho minus IC, positive = IC cheaper) that is NEGATIVE; symbolic magnitude 1.0 bit
# (the smallest value consistent with the sign is what matters; any negative value gives the same class).
sym = [{"tag": "coh-%s" % st, "n": 409, "storage": st, "omega": 3.0, "kappa": 1, "sembin_margin": -1.0, **PIN} for st in STORAGE]
cls = {}
for c in ("K-409", "B-409"):
    imp, ref = import_rows(sym, 409, 3.0, 1, True)
    cls[c] = classify_curve(imp, pc["delta_c"][c], tom[c]["MI-1"]["3.0"], naive_offered=pc["margin_vs_naive_2^(n/2)"])
res["PTM-C"] = {"naive_margin_offered_never_read": pc["margin_vs_naive_2^(n/2)"],
                "time_only_corrected": {c: tom[c]["MI-1"]["3.0"] for c in ("K-409", "B-409")},
                "curve_classes": {c: cls[c][:2] for c in cls},
                "degree_class": degree_class([cls[c][0] for c in cls]),
                "without_any_coherent_import": degree_class([classify_curve(None, 0, tom[c]["MI-1"]["3.0"])[0] for c in ("K-409", "B-409")]),
                "known_false_conclusion_reached": degree_class([cls[c][0] for c in cls]) == "MODEL-CLASS-IC"}
# --------------------------------------------------- PTM-C-SLICE: three mis-sliced imports at 409
good = {"n": 409, "omega": 3.0, "kappa": 1, "sembin_margin": -1.0, **PIN}
slices = {
  "cofactor-charged": [dict(good, storage=st, cofactor=2, tag="cof2-" + st) for st in STORAGE],
  "label-separated": [dict(good, storage=st, label_separated=True, tag="lab-" + st) for st in STORAGE],
  "time-only": [dict(good, storage=st, metric="time_only", sembin_margin=+37.78, tag="time-" + st) for st in STORAGE],
}
sl = {}
for name, rows in slices.items():
    imp, ref = import_rows(rows, 409, 3.0, 1, True)
    sl[name] = {"imported_values": imp, "refusals": ref[:2] + (["..."] if len(ref) > 2 else []),
                "all_refused": imp is not None and all(v is None for v in imp.values())}
# a fourth, unnamed case: two rows matching every pinned field, differing on an unpinned axis
dup = [dict(good, storage=st, alpha=a, tag="dup-%s-%s" % (st, a)) for st in STORAGE for a in (0.5, 1.0)]
imp, ref = import_rows(dup, 409, 3.0, 1, True)
sl["multi-match (unpinned alpha)"] = {"refusals": ref[:1] + ["..."], "all_refused": all(v is None for v in imp.values())}
res["PTM-C-SLICE"] = sl
# --------------------------------------------------- PTM-D: fake first-fall degree as D (IR-1)
def ir1_accepts_D(source):
    # IR-1: D is an integer grid variable 2..64 and nothing else; no value read from any file,
    # argument or record is ever assigned to D (V-2).
    return source == "grid"
