"""Annotate every diff -U0 hunk of spec v2-frozen -> v3 with YAML field paths.

Review computation (RB-4): text processing of committed bytes only. Reads the
two extracted spec files and the saved diff; prints one record per hunk.
"""
import re, sys, json

def line_paths(path):
    """Return list (1-based index) of key paths for each line, by indentation."""
    lines = open(path, encoding="utf-8").read().split("\n")
    stack = []  # (indent, label)
    out = [None]
    key_re = re.compile(r"^(\s*)(- )?([A-Za-z0-9_'\-\.\(\) ]+?):(\s|$)")
    item_re = re.compile(r"^(\s*)- (\{?)(id|stage|version|curve|joint)\s*:\s*([^,}]+)")
    for ln in lines:
        s = ln.rstrip()
        if not s.strip() or s.lstrip().startswith("#"):
            out.append(" / ".join(l for _, l in stack) + "  [comment/blank]" if s.lstrip().startswith("#") else " / ".join(l for _, l in stack))
            continue
        indent = len(s) - len(s.lstrip())
        m_item = item_re.match(s)
        m_key = key_re.match(s)
        label = None
        eff_indent = indent
        if m_item:
            label = f"[{m_item.group(3)}={m_item.group(4).strip()}]"
        elif s.lstrip().startswith("- "):
            # plain list item (string); label by first words
            txt = s.lstrip()[2:].strip()
            label = "[- " + txt[:28] + "]"
        elif m_key and not s.lstrip().startswith("- "):
            label = m_key.group(3).strip()
        if label is not None:
            while stack and stack[-1][0] >= eff_indent:
                stack.pop()
            stack.append((eff_indent, label))
            out.append(" / ".join(l for _, l in stack))
        else:
            # continuation line of a folded scalar: path of the enclosing key
            while stack and stack[-1][0] >= indent:
                stack.pop()
            out.append(" / ".join(l for _, l in stack) + " (cont)")
    return out, lines

def main(v2, v3, diffpath):
    p2, l2 = line_paths(v2)
    p3, l3 = line_paths(v3)
    hunks = []
    cur = None
    for ln in open(diffpath, encoding="utf-8").read().split("\n"):
        m = re.match(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", ln)
        if m:
            if cur: hunks.append(cur)
            a, b, c, d = m.groups()
            a = int(a); b = 1 if b is None else int(b)
            c = int(c); d = 1 if d is None else int(d)
            cur = {"hdr": ln, "v2_start": a, "v2_len": b, "v3_start": c, "v3_len": d, "minus": [], "plus": []}
        elif cur is not None:
            if ln.startswith("-") and not ln.startswith("---"):
                cur["minus"].append(ln[1:])
            elif ln.startswith("+") and not ln.startswith("+++"):
                cur["plus"].append(ln[1:])
    if cur: hunks.append(cur)
    for i, h in enumerate(hunks, 1):
        v2paths = sorted(set(p2[j] for j in range(h["v2_start"], h["v2_start"] + h["v2_len"]))) if h["v2_len"] else ["(insertion after v2 line %d: %s)" % (h["v2_start"], p2[h["v2_start"]] if h["v2_start"] < len(p2) else "")]
        v3paths = sorted(set(p3[j] for j in range(h["v3_start"], h["v3_start"] + h["v3_len"]))) if h["v3_len"] else ["(deletion)"]
        h["n"] = i
        h["v2_paths"] = v2paths
        h["v3_paths"] = v3paths
    return hunks

if __name__ == "__main__":
    hunks = main(sys.argv[1], sys.argv[2], sys.argv[3])
    mode = sys.argv[4] if len(sys.argv) > 4 else "summary"
    for h in hunks:
        if mode == "summary":
            print(f"H{h['n']:02d} {h['hdr']}")
            for p in h["v3_paths"][:6]:
                print("    v3:", p[:150])
        elif mode == "json":
            pass
    if mode == "json":
        print(json.dumps(hunks, indent=0)[:200])

